window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8053d731e21a79bd"]={"versions": [{"id": "FIG-8053d731e21a79bd", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR Generic Structure Template (TPS Generic Structure Template). Das Diagramm definiert die Modellierung und semantische Typisierung von Post-Build-Variantenkriterien (<code>PostBuildVariantCriterion</code>) über Berechnungsmethoden (<code>CompuMethod</code>) im Rahmen des AUTOSAR-Variantenmanagements.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst zwei Klassen und deren Assoziation:</p>\n<ul class=\"fig-list\"><li><code>PostBuildVariantCriterion</code>:\n<ul class=\"fig-list\"><li>Stereotypen: <code>«ARElement»</code>, <code>«AtpDefinition»</code>\n</li><li>Repräsentiert die Definition eines Kriteriums zur Steuerung von Post-Build-Varianten.\n</li></ul>\n</li><li><code>CompuMethod</code>:\n<ul class=\"fig-list\"><li>Stereotypen: <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>\n</li><li>Attribut: <code>+ displayFormat: DisplayFormatString [0..1]</code>\n</li><li>Dient der rechnerischen Umrechnung bzw. Wertbereichs- und Skaleninterpretation für das Kriterium.\n</li></ul>\n</li><li>Assoziation:\n<ul class=\"fig-list\"><li>Gerichtete Assoziation von <code>PostBuildVariantCriterion</code> auf <code>CompuMethod</code>.\n</li><li>Rollenname am Zielende: <code>+compuMethod</code>\n</li><li>Multiplizität: exakt <code>1</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Struktur- bzw. Metamodell-Diagramm ohne Verhaltens- oder Sequenzdarstellung. Die Instanziierung erfolgt statisch im Rahmen der AUTOSAR-Modellierung, wobei jedes PostBuildVariantCriterion zur Festlegung seiner semantischen Werte und Berechnungsregeln auf genau eine definierte CompuMethod referenziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Metamodell-Struktur für AUTOSAR-Autorenwerkzeuge und Codegeneratoren:</p>\n<ul class=\"fig-list\"><li>Jedes <code>PostBuildVariantCriterion</code> muss zwingend über die Rolle <code>compuMethod</code> mit genau einer Instanz vom Typ <code>CompuMethod</code> (Multiplizität <code>1</code>) verknüpft sein.\n</li><li>Die referenzierte <code>CompuMethod</code> kann optional ein Anzeigeformat über <code>displayFormat</code> definieren (<code>[0..1]</code>).\n</li><li>Beide Klassen sind spezialisierte <code>ARElement</code>-Typen und besitzen damit Top-Level-Paketierbarkeit im ARXML-Datenmodell.\n</li></ul>"}, {"id": "FIG-89c1d88161a17013", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR Generic Structure Template (TPS Generic Structure Template). Das Diagramm definiert die Modellierung und semantische Typisierung von Post-Build-Variantenkriterien (<code>PostBuildVariantCriterion</code>) über Berechnungsmethoden (<code>CompuMethod</code>) im Rahmen des AUTOSAR-Variantenmanagements.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst zwei Klassen und deren Assoziation:</p>\n<ul class=\"fig-list\"><li><code>PostBuildVariantCriterion</code>:\n<ul class=\"fig-list\"><li>Stereotypen: <code>«ARElement»</code>, <code>«AtpDefinition»</code>\n</li><li>Repräsentiert die Definition eines Kriteriums zur Steuerung von Post-Build-Varianten.\n</li></ul>\n</li><li><code>CompuMethod</code>:\n<ul class=\"fig-list\"><li>Stereotypen: <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>\n</li><li>Attribut: <code>+ displayFormat: DisplayFormatString [0..1]</code>\n</li><li>Dient der rechnerischen Umrechnung bzw. Wertbereichs- und Skaleninterpretation für das Kriterium.\n</li></ul>\n</li><li>Assoziation:\n<ul class=\"fig-list\"><li>Gerichtete Assoziation von <code>PostBuildVariantCriterion</code> auf <code>CompuMethod</code>.\n</li><li>Rollenname am Zielende: <code>+compuMethod</code>\n</li><li>Multiplizität: exakt <code>1</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Struktur- bzw. Metamodell-Diagramm ohne Verhaltens- oder Sequenzdarstellung. Die Instanziierung erfolgt statisch im Rahmen der AUTOSAR-Modellierung, wobei jedes PostBuildVariantCriterion zur Festlegung seiner semantischen Werte und Berechnungsregeln auf genau eine definierte CompuMethod referenziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Metamodell-Struktur für AUTOSAR-Autorenwerkzeuge und Codegeneratoren:</p>\n<ul class=\"fig-list\"><li>Jedes <code>PostBuildVariantCriterion</code> muss zwingend über die Rolle <code>compuMethod</code> mit genau einer Instanz vom Typ <code>CompuMethod</code> (Multiplizität <code>1</code>) verknüpft sein.\n</li><li>Die referenzierte <code>CompuMethod</code> kann optional ein Anzeigeformat über <code>displayFormat</code> definieren (<code>[0..1]</code>).\n</li><li>Beide Klassen sind spezialisierte <code>ARElement</code>-Typen und besitzen damit Top-Level-Paketierbarkeit im ARXML-Datenmodell.\n</li></ul>"}], "trans": [{"from": "FIG-8053d731e21a79bd", "to": "FIG-89c1d88161a17013", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
